sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    try {
        //5745 calling EL outound API 
        var grOutBound = new GlideRecord('x_hsb11_mss_c_ghss_hsbc_ghss_outbound_table');
        grOutBound.get(current.getValue('sys_id'));

        var gcpOutboundToken = gs.getProperty('x_hsb11_hsbc_mss_o.eventOutbound_GCP_token');
        var endpoint = gs.getProperty('x_hsb11_mss_c_ghss.EL_Outbound_EndPoint');
        var r = new sn_ws.RESTMessageV2('x_hsb11_mss_c_ghss.Amend Outbound API', 'Amend Trade');
        r.setEndpoint(endpoint);
        r.setRequestHeader('Authorization', 'Bearer ' + gcpOutboundToken);
        r.setRequestHeader('Content-Type', 'application/x-www-form-urlencoded');

        // MSSCUSTODY-6283
        var encodedPayload = gs.base64Encode(grOutBound.request_body);
        var requestBody = 'data=' + encodeURIComponent(encodedPayload);

        // gs.info('Amend Request Body ' + encodeURIComponent(requestBody));
        r.setRequestBody(requestBody); //encoding to UTF- 8 since the content type is URL encoded

        var response = r.executeAsync();
        var responseBody = response.getBody();
        var statuscode = response.getStatusCode();

        gs.info('Status code from EL for task ' + grOutBound.sn_task.number + 'request Code' + statuscode + ' Bulk Reference ' + grOutBound.sn_task.bulk_id.number);

        var statusMessage = responseBody.replaceAll(" ", "").toString().toLowerCase();

        var taskGR = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
        taskGR.get(grOutBound.sn_task.sys_id);

        gs.info('Status code from EL for task ' + grOutBound.sn_task.number + 'with BULK ID ' + grOutBound.sn_task.number + " " + statusMessage + 'Status Code Received ' + statuscode);

        if (statuscode == 202) { //RequestAcceptedforprocessing
            gs.info('Status code from EL for task Loop1');
            taskGR.state = 6; // Set state to awaiting info
            grOutBound.state = 'processing_rpa';
            grOutBound.response_body = statusMessage;
            grOutBound.response_code = statuscode;
        } else {
            gs.info('Status code from EL for task Loop2');
            taskGR.state = 4; // Set state to closed rejected
            grOutBound.state = 'error_rpa';
            grOutBound.response_body = responseBody;
            grOutBound.response_code = statuscode;
        }
        grOutBound.update();
        taskGR.update();

    } catch (e) {
        gs.info('Business rule MSS Custody Amend EL Outbound errored with ' + e.message);
    }




})(current, previous);
